mapper.select:
select pb.uuid as "branchUuid", pb.project_uuid as "projectUuid", pb.kee as "branchKey", pb.branch_type as "branchType", pb.pull_request_binary as "pullRequestBinary",
coalesce( tb.kee, case when d.target_branch_uuid = pb.merge_branch_uuid then d.target_branch_key end, (select td.branch_key from cs_retain_details td where td.branch_uuid = pb.merge_branch_uuid) ) as "targetBranchKey", case when pb.branch_type = 'PULL_REQUEST' then pb.merge_branch_uuid end as "targetBranchUuid", o.retain_issue_history_enabled as "retainEnabled", d.branch_uuid as "retainedBranchUuid", d.branch_key as "retainedBranchKey", d.branch_name as "retainedBranchName", d.target_branch_key as "retainedTargetBranchKey", d.target_branch_uuid as "retainedTargetBranchUuid" from project_branches pb inner join projects p on p.uuid = pb.project_uuid inner join organizations o on o.uuid = p.organization_uuid
left join project_branches tb on tb.uuid = pb.merge_branch_uuid and pb.branch_type = 'PULL_REQUEST' left join cs_retain_details d on d.branch_uuid = pb.uuid where pb.uuid = #{branchUuid, jdbcType=VARCHAR}

select case when exists (
  select 1 from cs_issue_track_for_retain where branch_uuid = #{branchUuid, jdbcType=VARCHAR}
) then 1 else 0 end

mapper.update:
update cs_retain_details set
  branch_key = #{dto.branchKey, jdbcType=VARCHAR},
  branch_name = #{dto.branchName, jdbcType=VARCHAR},
  target_branch_key = #{dto.targetBranchKey, jdbcType=VARCHAR},
  target_branch_uuid = #{dto.targetBranchUuid, jdbcType=VARCHAR}
where branch_uuid = #{dto.branchUuid, jdbcType=VARCHAR}

mapper.sql:

where
  i.kee in

    #{issueKey, jdbcType=VARCHAR}

  and i.issue_type <> #{excludedIssueType, jdbcType=INTEGER}

  and (i.status = 'CLOSED' or (i.status = 'RESOLVED' and i.resolution = 'FIXED'))

  and i.rule_uuid is not null


where
  i.component_uuid in

    #{componentUuid, jdbcType=VARCHAR}

  and i.issue_close_date = #{now, jdbcType=BIGINT}
  and i.status = 'CLOSED'
  and i.issue_type <> #{excludedIssueType, jdbcType=INTEGER}
  and i.rule_uuid is not null

mapper.delete:
delete from cs_issue_track_for_retain
where
  retained_status = #{retainedStatus, jdbcType=VARCHAR}
  and issue_kee in

    #{issueKey, jdbcType=VARCHAR}



  and not exists (
    select 1 from issues i
    where i.kee = cs_issue_track_for_retain.issue_kee
      and (i.status = 'CLOSED' or (i.status = 'RESOLVED' and i.resolution = 'FIXED'))
  )

mapper.update:
update cs_issue_track_for_retain set (status, resolution, status_changed_at) = ( select i.status, i.resolution, coalesce(i.issue_close_date, cs_issue_track_for_retain.status_changed_at) from issues i where i.kee = cs_issue_track_for_retain.issue_kee ) where retained_status = 'FIXED' and issue_kee in
#{issueKey, jdbcType=VARCHAR}
and exists (select 1 from issues i where i.kee = cs_issue_track_for_retain.issue_kee)

update cs_retain_details set deleted_at = #{now, jdbcType=BIGINT}, (branch_key, branch_name, target_branch_uuid, target_branch_key) = ( select coalesce(pb.kee, cs_retain_details.branch_key),
case when cs_retain_details.branch_type = 'PULL_REQUEST' then cs_retain_details.branch_name else coalesce(pb.kee, cs_retain_details.branch_name) end, case when cs_retain_details.branch_type = 'PULL_REQUEST' then coalesce(pb.merge_branch_uuid, cs_retain_details.target_branch_uuid) else cs_retain_details.target_branch_uuid end,
case when cs_retain_details.branch_type <> 'PULL_REQUEST' or pb.uuid is null then cs_retain_details.target_branch_key else coalesce( tb.kee, case when cs_retain_details.target_branch_uuid = pb.merge_branch_uuid then cs_retain_details.target_branch_key end, (select td.branch_key from cs_retain_details td where td.branch_uuid = pb.merge_branch_uuid)) end from (select 1 as one) one_row left join project_branches pb on pb.uuid = #{branchUuid, jdbcType=VARCHAR} left join project_branches tb on tb.uuid = pb.merge_branch_uuid ) where branch_uuid = #{branchUuid, jdbcType=VARCHAR}

mapper.delete:
delete from cs_issue_track_for_retain
where branch_uuid in (
  select d.branch_uuid
  from cs_retain_details d
  where d.project_uuid = #{projectUuid, jdbcType=VARCHAR}
)
